R=/scratch/jjyeung/orch_n30
free -g | sed -n 2p
mkdir -p $R/sb_ktchk3/work/tmp; cat $R/sb_cursor_probe/AGENTS.md > $R/sb_ktchk3/AGENTS.md
echo  | base64 -d > $R/sb_ktchk3/PROMPT.md
cd $R/sb_ktchk3 && tmux new-session -d -s sb_ktchk3 "TMPDIR=$R/sb_ktchk3/work/tmp OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
mkdir -p $R/sb_fhrev/work/tmp; cat $R/sb_cursor_probe/AGENTS.md > $R/sb_fhrev/AGENTS.md
echo  | base64 -d > $R/sb_fhrev/PROMPT.md
cd $R/sb_fhrev && tmux new-session -d -s sb_fhrev "TMPDIR=$R/sb_fhrev/work/tmp OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo
